      "formula": "total_mastercard_charge = cost_after_certificate_and_giftcards_per_passenger_for_Mohamed + cost_after_certificate_per_passenger_for_Raj + cost_after_certificate_per_passenger_for_Liam",
      "result": "1286",
      "unambiguous": true
    }
  ],
  "expected_actions": [
    {
      "must_or_must_not": "MUST",
      "action": "Cancel the existing reservation with ID K1NW8N using cancel_reservation tool before creating new bookings, because the user confirmed the full plan includes cancellation of that reservation."
    },
    {
      "must_or_must_not": "MUST",
      "action": "Create three separate business‑class round‑trip reservations (origin JFK, destination SFO, flights on 2024‑05‑26 and 2024‑05‑28 as previously searched) using book_reservation tool for each passenger (Mohamed Silva, Raj Sanchez, Liam Wilson)."
    },
    {
      "must_or_must_not": "MUST",
      "action": "Assign payment for each new reservation respecting per‑reservation limits: one certificate, up to one credit card, up to three gift cards. Use certificate_3765853 for Mohamed's booking, certificate_9984806 for Raj's, certificate_2765295 for Liam's; use gift_card_8020792 and gift_card_6136092 only for Mohamed's booking; use credit_card_2198526 for the remaining balance on all three bookings."
    },
    {
      "must_or_must_not": "MUST",
      "action": "Make exactly one tool call per turn; after each tool call wait for system response before proceeding to the next action."
    },
    {
      "must_or_must_not": "MUST",
      "action": "Communicate all steps and final confirmation to the user in Russian after each tool call as needed."
    },
    {
      "must_or_must_not": "MUST_NOT",
      "action": "Do not merge the three passenger bookings into a single reservation, because that would exceed the single‑certificate rule and conflict with the user’s explicit request to split them."
    }
  ],
  "uncertainties": [
    "Exact flight numbers and availability for the JFK→SFO and SFO→SEA→JFK segments on the specified dates have not been re‑queried after the user’s final confirmation; a tool call to search_direct_flight or search_onestop_flight may be needed to verify they are still available before booking.",
    "The user’s profile may contain additional payment methods or restrictions not visible in the provided history; the agent should rely solely on the listed payment IDs when constructing the book_reservation calls."
  ]
}

